import { useRef } from "react";

// The ordered-list markers are generated by the browser, outside editable text.
export function RulesEditor({ initialRules, onChange }) {
  const editor = useRef(null);
  const initial = useRef(initialRules.length ? initialRules : [""]);
  function publish() {
    if (
      !editor.current.children.length ||
      Array.from(editor.current.children).some((item) => item.tagName !== "LI")
    ) {
      const lines = editor.current.innerText.split(/\r?\n/);
      editor.current.replaceChildren(
        ...lines.map((line) => {
          const item = document.createElement("li");
          item.textContent = line;
          if (!line) item.append(document.createElement("br"));
          return item;
        }),
      );
    }
    const items = Array.from(editor.current.children).map(
      (item) => item.textContent || "",
    );
    onChange(items);
  }
  function insertLines(lines) {
    const selection = window.getSelection();
    if (!selection.rangeCount) return;
    const range = selection.getRangeAt(0);
    if (!editor.current.contains(range.commonAncestorContainer)) return;
    range.deleteContents();
    let item =
      selection.anchorNode?.nodeType === Node.ELEMENT_NODE
        ? selection.anchorNode.closest("li")
        : selection.anchorNode?.parentElement.closest("li");
    if (!item || item.parentElement !== editor.current) {
      item = document.createElement("li");
      editor.current.append(item);
      range.selectNodeContents(item);
      range.collapse(false);
    }
    const tail = range.cloneRange();
    tail.setEndAfter(item.lastChild || item);
    // Empty list items have no tail to preserve.
    const remainder = item.lastChild
      ? tail.extractContents()
      : document.createDocumentFragment();
    const first = document.createTextNode(lines[0]);
    range.insertNode(first);
    let cursor = first;
    for (const line of lines.slice(1)) {
      const next = document.createElement("li");
      cursor = document.createTextNode(line);
      next.append(cursor);
      item.after(next);
      item = next;
    }
    item.append(remainder);
    if (!item.textContent) item.append(document.createElement("br"));
    range.setStartAfter(cursor);
    range.collapse(true);
    selection.removeAllRanges();
    selection.addRange(range);
    publish();
  }
  function insertSoftLine() {
    const selection = window.getSelection();
    if (!selection.rangeCount) return;
    const range = selection.getRangeAt(0);
    const node = range.startContainer;
    const item =
      node.nodeType === Node.ELEMENT_NODE
        ? node.closest?.("li")
        : node.parentElement?.closest("li");
    if (item?.parentElement !== editor.current) return;
    range.deleteContents();
    const lineBreak = document.createTextNode("\n");
    range.insertNode(lineBreak);
    range.setStart(lineBreak, 1);
    range.collapse(true);
    selection.removeAllRanges();
    selection.addRange(range);
    publish();
  }
  return (
    <div className="ca-rules-box">
      <ol
        ref={editor}
        role="textbox"
        aria-label="Event rules"
        aria-multiline="true"
        contentEditable
        suppressContentEditableWarning
        onInput={publish}
        onKeyDown={(event) => {
          if (event.key === "Backspace") {
            const selection = window.getSelection();
            if (selection.isCollapsed && selection.rangeCount) {
              const range = selection.getRangeAt(0);
              const first = editor.current.firstElementChild;
              if (first?.contains(range.startContainer)) {
                const prefix = range.cloneRange();
                prefix.selectNodeContents(first);
                prefix.setEnd(range.startContainer, range.startOffset);
                if (!prefix.toString()) event.preventDefault();
              }
            }
          }
          if (event.key === "Enter" && !event.nativeEvent.isComposing) {
            event.preventDefault();
            if (event.shiftKey) insertSoftLine();
            else insertLines(["", ""]);
          }
          if (
            ["Backspace", "Delete"].includes(event.key) &&
            !editor.current.textContent
          ) {
            event.preventDefault();
          }
          if (
            (event.ctrlKey || event.metaKey) &&
            ["b", "i", "u"].includes(event.key.toLowerCase())
          )
            event.preventDefault();
        }}
        onPaste={(event) => {
          event.preventDefault();
          insertLines(
            event.clipboardData
              .getData("text/plain")
              .split(/\r?\n/)
              .map((line) => line.replace(/^\s*(?:[•●*-]\s+|\d+[.)]\s+)/, "")),
          );
        }}
      >
        {initial.current.map((point, index) => (
          <li key={index}>{point || <br />}</li>
        ))}
      </ol>
    </div>
  );
}
